// TMM B20 — guaranteed wandering trader magic stock, MC 1.21.1 / NeoForge / KubeJS 2101.
//
// IMPORTANT: WandererTradesEvent only expands a RANDOM TRADE POOL. We instead append
// five offers to the actual merchant's offers when it joins a SERVER world.
// Persistent stock version prevents duplication when chunks reload.
//
// Apotheosis: a truly affixed random item generated by the active Apotheosis API.
// Ars: one enabled/non-starter glyph each from live configured tier I, II, III.
// Iron's: one Uncommon-or-higher ink, weighted toward Uncommon.
// Existing vanilla and Iron's normal random trades are retained.
// NOT GAMEPLAY CERTIFIED until server + client smoke and real merchant testing.

const TMM_StockVersion = 1;
const TMM_Offer = Java.loadClass('net.minecraft.world.item.trading.MerchantOffer');
const TMM_Cost = Java.loadClass('net.minecraft.world.item.trading.ItemCost');
const TMM_Stack = Java.loadClass('net.minecraft.world.item.ItemStack');
const TMM_Items = Java.loadClass('net.minecraft.world.item.Items');
const TMM_Optional = Java.loadClass('java.util.Optional');
const TMM_GenContext = Java.loadClass('dev.shadowsoffire.apotheosis.tiers.GenContext');
const TMM_WorldTier = Java.loadClass('dev.shadowsoffire.apotheosis.tiers.WorldTier');
const TMM_Rarity = Java.loadClass('dev.shadowsoffire.apotheosis.loot.LootRarity');
const TMM_LootController = Java.loadClass('dev.shadowsoffire.apotheosis.loot.LootController');
const TMM_Affixes = Java.loadClass('dev.shadowsoffire.apotheosis.affix.AffixHelper');
const TMM_GlyphRegistry = Java.loadClass('com.hollingsworth.arsnouveau.api.registry.GlyphRegistry');
const TMM_ArsConfig = Java.loadClass('com.hollingsworth.arsnouveau.setup.config.Config');
const TMM_InkItems = Java.loadClass('io.redspace.ironsspellbooks.registries.ItemRegistry');

function tmmTrade(stack, emeralds, extraItem, extraCount, maxUses) {
  if (stack === null || stack.isEmpty()) throw new Error('Empty magical trade output');
  if (emeralds < 1 || emeralds > 64) throw new Error('Emerald cost out of bounds: ' + emeralds);
  const cost = new TMM_Cost(TMM_Items.EMERALD, emeralds);
  const additional = extraItem === null
    ? TMM_Optional.empty()
    : TMM_Optional.of(new TMM_Cost(extraItem, extraCount));
  return new TMM_Offer(cost, additional, stack, maxUses, 0, 0.05);
}

function tmmAffixGear(trader) {
  const level = trader.level();
  const rand = trader.getRandom();
  let ctx;
  // A trader is usually spawned near a player. Use that player's own Apotheosis
  // world tier, rather than giving early-game players PINNACLE-tier affixes.
  try {
    const nearby = level.getNearestPlayer(trader, 96.0);
    ctx = nearby === null
      ? TMM_GenContext.standalone(rand, TMM_WorldTier.HAVEN, 0.0, level, trader.blockPosition())
      : TMM_GenContext.forPlayerAtPos(rand, nearby, trader.blockPosition());
  } catch (e) {
    console.warn('[TMM Trader] Nearest-player tier unavailable, using HAVEN: ' + e);
    ctx = TMM_GenContext.standalone(rand, TMM_WorldTier.HAVEN, 0.0, level, trader.blockPosition());
  }

  let gear = null;
  // Generate from the ACTUAL active Apotheosis loot entry pool and reject
  // un-affixed items, not just items that carry a fancy name or enchantments.
  for (let attempt = 0; attempt < 32; attempt++) {
    const candidate = TMM_LootController.createRandomLootItem(ctx, null);
    if (candidate !== null && !candidate.isEmpty() && TMM_Affixes.hasAffixes(candidate)) {
      gear = candidate;
      break;
    }
  }

  // When a dimension has no matching random loot entries, try normal equipment
  // with Apotheosis' own affix generator. Never substitute a plain item.
  if (gear === null) {
    const bases = [TMM_Items.IRON_SWORD, TMM_Items.IRON_CHESTPLATE,
                   TMM_Items.IRON_PICKAXE, TMM_Items.IRON_BOOTS];
    for (let i = 0; i < 16 && gear === null; i++) {
      const rarity = TMM_Rarity.random(ctx);
      if (rarity === null) continue;
      const candidate = TMM_LootController.createLootItem(
        new TMM_Stack(bases[i % bases.length]), rarity, ctx);
      if (!candidate.isEmpty() && TMM_Affixes.hasAffixes(candidate)) gear = candidate;
    }
  }
  if (gear === null) throw new Error('No valid affixed gear from active Apotheosis loot/affix rules');

  // Price scales with the generation world tier. These are *offers*, not
  // automatic gifts: a trader has just one piece, with only one purchase.
  const tier = String(ctx.tier().getSerializedName());
  const prices = {
    haven: [24, 1],
    frontier: [32, 2],
    ascent: [40, 4],
    summit: [56, 8],
    pinnacle: [64, 12]
  };
  const p = prices[tier] || prices.haven;
  return tmmTrade(gear, p[0], TMM_Items.DIAMOND, p[1], 1);
}

function tmmGlyphForTier(trader, tier) {
  const suppliers = TMM_GlyphRegistry.getGlyphItemMap().values().toArray();
  const starters = TMM_GlyphRegistry.getDefaultStartingSpells();
  const choices = [];
  for (let i = 0; i < suppliers.length; i++) {
    const glyph = suppliers[i].get();
    if (glyph === null || glyph.spellPart === null) continue;
    const part = glyph.spellPart;
    if (!part.isEnabled() || !TMM_ArsConfig.isGlyphEnabled(part.getRegistryName())) continue;
    if (starters.contains(part)) continue;
    if (Number(part.getConfigTier().value) === tier) choices.push(glyph);
  }
  if (choices.length === 0) throw new Error('No enabled non-starter Ars glyphs at tier ' + tier);
  const glyph = choices[trader.getRandom().nextInt(choices.length)];
  if (tier === 1) return tmmTrade(new TMM_Stack(glyph), 12, null, 0, 1);
  if (tier === 2) return tmmTrade(new TMM_Stack(glyph), 28, TMM_Items.LAPIS_LAZULI, 4, 1);
  return tmmTrade(new TMM_Stack(glyph), 48, TMM_Items.DIAMOND, 4, 1);
}

function tmmInkOffer(trader) {
  const roll = trader.getRandom().nextInt(100);
  // 55% Uncommon, 30% Rare, 12% Epic, 3% Legendary.
  // Never allow Common Ink in the guaranteed slot.
  if (roll < 55) return tmmTrade(new TMM_Stack(TMM_InkItems.INK_UNCOMMON.get()), 16, null, 0, 3);
  if (roll < 85) return tmmTrade(new TMM_Stack(TMM_InkItems.INK_RARE.get()), 28, null, 0, 2);
  if (roll < 97) return tmmTrade(new TMM_Stack(TMM_InkItems.INK_EPIC.get()), 48, TMM_Items.DIAMOND, 2, 1);
  return tmmTrade(new TMM_Stack(TMM_InkItems.INK_LEGENDARY.get()), 64, TMM_Items.DIAMOND, 8, 1);
}

// B20.1 — Player-approved premium rotation. Vanilla and Iron's stock remain intact.
// Four distinct items per trader are drawn from the approved ten-item catalog.
// 1–128 emeralds via MerchantOffer's two price slots, capped at one purchase
// except inexpensive consumables. No ore, boss trophies, or completed progression gates.
const TMM_PremiumVersion = 1;
const TMM_CollectibleStockVersion = 1;
const TMM_Builtins = Java.loadClass('net.minecraft.core.registries.BuiltInRegistries');
const TMM_RL = Java.loadClass('net.minecraft.resources.ResourceLocation');

function tmmKnownItem(id) {
  const item = TMM_Builtins.ITEM.get(TMM_RL.parse(id));
  if (item === null || String(TMM_Builtins.ITEM.getKey(item)) !== id) {
    throw new Error('[TMM Trader] Missing registered item ' + id);
  }
  return item;
}

function tmmNormalStack(id) { return new TMM_Stack(tmmKnownItem(id)); }

function tmmExpensiveTrade(stack, emeralds, maxUses) {
  if (emeralds < 1 || emeralds > 128) throw new Error('Premium emerald price out of bounds: ' + emeralds);
  return emeralds <= 64
    ? tmmTrade(stack, emeralds, null, 0, maxUses)
    : tmmTrade(stack, 64, TMM_Items.EMERALD, emeralds - 64, maxUses);
}

function tmmRandomEvilcraftBroom(trader) {
  // Reuses EvilCraft's own broom-part/modifier registries, as its loot modifier does.
  // The broom is uncharged: the buyer supplies their own blood to power sustained flight.
  const BroomParts = Java.loadClass('org.cyclops.evilcraft.core.broom.BroomParts');
  const BroomMods = Java.loadClass('org.cyclops.evilcraft.api.broom.BroomModifiers');
  const JList = Java.loadClass('java.util.ArrayList');
  const JMap = Java.loadClass('java.util.HashMap');
  const parts = BroomParts.REGISTRY.getParts().toArray();
  const random = trader.getRandom();
  function randomPart(prefix) {
    const matches = [];
    for (let i = 0; i < parts.length; i++) {
      if (String(parts[i].getId().getPath()).startsWith(prefix)) matches.push(parts[i]);
    }
    if (matches.length === 0) throw new Error('No EvilCraft broom parts for ' + prefix);
    return matches[random.nextInt(matches.length)];
  }
  const stack = tmmNormalStack('evilcraft:broom');
  const selected = new JList();
  selected.add(randomPart('rod'));
  selected.add(randomPart('brush'));
  selected.add(randomPart('cap'));
  BroomParts.REGISTRY.setBroomParts(stack, selected);

  const options = BroomMods.REGISTRY.getModifiers().toArray();
  if (options.length < 2) throw new Error('EvilCraft has fewer than two broom modifiers');
  const a = random.nextInt(options.length);
  let b = random.nextInt(options.length - 1);
  if (b >= a) b++;
  const picked = new JMap();
  picked.put(options[a], options[a].getTierValue());
  picked.put(options[b], options[b].getTierValue());
  BroomMods.REGISTRY.setModifiers(stack, picked);
  return stack;
}

function tmmFullManaTablet() {
  // IMPORTANT: normal charged item, never creative_mana_tablet or creative flag.
  const BotaniaItems = Java.loadClass('velrondevs.botania.registry.BotaniaItems');
  const ManaTablet = Java.loadClass('velrondevs.botania.common.item.ManaTabletItem');
  const tablet = new TMM_Stack(BotaniaItems.manaTablet);
  ManaTablet.setMana(tablet, ManaTablet.MAX_MANA); // normal 500,000 mana
  return tablet;
}

function tmmRandomBotaniaCurio(trader) {
  const BotaniaItems = Java.loadClass('velrondevs.botania.registry.BotaniaItems');
  // No Gaia rings, creative items, or high-tier boss reward accessories.
  const eligible = [
    BotaniaItems.magnetRing, BotaniaItems.manaRing, BotaniaItems.auraRing,
    BotaniaItems.reachRing, BotaniaItems.waterRing, BotaniaItems.miningRing
  ];
  const choice = eligible[trader.getRandom().nextInt(eligible.length)];
  if (choice === null) throw new Error('No Botania non-boss curio in selected pool');
  return new TMM_Stack(choice);
}

function tmmRareTheurgyNiter(trader) {
  const ids = [
    'theurgy:alchemical_niter_metals_rare',
    'theurgy:alchemical_niter_gems_rare',
    'theurgy:alchemical_niter_mobs_rare',
    'theurgy:alchemical_niter_other_minerals_rare'
  ];
  return tmmNormalStack(ids[trader.getRandom().nextInt(ids.length)]);
}

const TMM_PremiumCatalog = [
  {id: 'occultism_iesnium_ingot', price: 96, uses: 1,
   make: trader => tmmNormalStack('occultism:iesnium_ingot')},
  {id: 'astral_undiscovered_constellation', price: 48, uses: 1,
   // EMPTY paper: Astral 1.21.1 will assign only constellations the buyer
   // is currently eligible to discover according to its own research API.
   make: trader => tmmNormalStack('astralsorcery:constellation_paper')},
  {id: 'evilcraft_random_broom', price: 112, uses: 1,
   make: trader => tmmRandomEvilcraftBroom(trader)},
  {id: 'botania_full_mana_tablet', price: 128, uses: 1,
   make: trader => tmmFullManaTablet()},
  {id: 'botania_random_curio', price: 80, uses: 1,
   make: trader => tmmRandomBotaniaCurio(trader)},
  {id: 'botania_black_lotus', price: 32, uses: 2,
   make: trader => tmmNormalStack('botania:black_lotus')},
  {id: 'rootsclassic_runic_focus', price: 72, uses: 1,
   // Runic Focus is a precursor to Engraved Blade; sword ritual still required.
   // Terra Moss is NOT an item in installed Roots Classic 1.5.10.
   make: trader => tmmNormalStack('rootsclassic:runic_focus')},
  {id: 'malum_brilliance_chunk', price: 48, uses: 1,
   // Does not substitute Weeping Well discovery or rare Umbral Spirit.
   make: trader => tmmNormalStack('malum:chunk_of_brilliance')},
  {id: 'theurgy_rare_niter', price: 56, uses: 1,
   make: trader => tmmRareTheurgyNiter(trader)},
  {id: 'forbidden_arcanus_growing_edelwood', price: 64, uses: 1,
   // The mod's plantable Edelwood equivalent is "Growing Edelwood".
   make: trader => tmmNormalStack('forbidden_arcanus:growing_edelwood')},
  {id: 'witchery_drop_of_luck', price: 96, uses: 1,
   // Major witchcraft crafting-time saver, not the finished ritual result.
   make: trader => tmmNormalStack('witchery:drop_of_luck')},
  {id: 'hexerei_replacer_satchel', price: 96, uses: 1,
   // Genuine broom brush-replacement satchel; normal broom setup still required.
   make: trader => tmmNormalStack('hexerei:replacer_satchel')}
];


// B20.2 — guaranteed one genuinely registered Relic OR Artifact, never a
// generic renamed accessory. Native Relic default stacks are how Relic's own
// loot generation populates its rewards; Reliquified Artifacts can initialize
// its progression data through the normal item mechanics.
// Deliberately select *items*, not bosses, consumable materials, or placeholders.
const TMM_RelicItem = Java.loadClass('it.hurts.sskirillss.relics.items.relics.base.RelicItem');
const TMM_ArtifactItem = Java.loadClass('artifacts.item.ArtifactItem');

// These remain registered even when excluded from world loot. Do not allow
// the merchant's dynamic item registry scan to reintroduce them.
const TMM_ForbiddenTraderItemIds = ['relics:ring_of_the_seven_deadly_sins'];

function tmmIsForbiddenTraderItem(item) {
  return TMM_ForbiddenTraderItemIds.includes(String(TMM_Builtins.ITEM.getKey(item)));
}

// Defense in depth: remove blacklisted results from ANY existing offers,
// not only this script's own random Relic/Artifact selection. Run before
// checking stock markers so old traders get cleaned up on chunk load.
function tmmPurgeForbiddenTraderOffers(trader) {
  const offers = trader.getOffers();
  for (let i = offers.size() - 1; i >= 0; i--) {
    const result = offers.get(i).getResult();
    if (result !== null && !result.isEmpty() && tmmIsForbiddenTraderItem(result.getItem())) {
      offers.remove(i);
      console.warn('[TMM Trader] Removed forbidden trade offer: ' +
        String(TMM_Builtins.ITEM.getKey(result.getItem())));
    }
  }
}

function tmmRandomRelicOrArtifact(trader) {
  const relics = [];
  const artifacts = [];
  const entries = TMM_Builtins.ITEM.entrySet().toArray();

  for (let i = 0; i < entries.length; i++) {
    const item = entries[i].getValue();
    if (tmmIsForbiddenTraderItem(item)) continue;
    if (item instanceof TMM_RelicItem) {
      relics.push(item);
    } else if (item instanceof TMM_ArtifactItem && !item.isCosmetic()) {
      artifacts.push(item);
    }
  }

  if (relics.length === 0 && artifacts.length === 0) {
    throw new Error('Neither Relics nor Artifacts has a valid registered item');
  }

  // Equal odds between the two MOD FAMILIES, not weighted by registry size.
  // If one mod has no valid item, offer one from the other; never an empty offer.
  const random = trader.getRandom();
  const selectedFamily = artifacts.length === 0 ? 'relics'
    : relics.length === 0 ? 'artifacts'
    : random.nextBoolean() ? 'relics' : 'artifacts';

  const options = selectedFamily === 'relics' ? relics : artifacts;
  const item = options[random.nextInt(options.length)];
  const stack = item.getDefaultInstance(); // Relics' own loot uses this API
  if (stack === null || stack.isEmpty()) throw new Error('Empty ' + selectedFamily + ' stack');
  if (tmmIsForbiddenTraderItem(stack.getItem())) {
    throw new Error('Forbidden Relic/Artifact trade output rejected');
  }
  const cost = selectedFamily === 'relics' ? 128 : 96;
  return {family: selectedFamily, itemId: String(TMM_Builtins.ITEM.getKey(item)),
          offer: tmmExpensiveTrade(stack, cost, 1)};
}

function tmmPremiumRotation(trader, count) {
  const pool = TMM_PremiumCatalog.slice();
  const chosen = [];
  if (count > pool.length) throw new Error('Not enough trader premium types');
  while (pool.length > 0 && chosen.length < count) {
    const index = trader.getRandom().nextInt(pool.length);
    const picked = pool.splice(index, 1)[0];
    try {
      // A missing registry ID/API must not prevent other valid stock from being
      // offered. Retry with a different item, never counterfeit missing items.
      const stack = picked.make(trader);
      chosen.push({id: picked.id, offer: tmmExpensiveTrade(stack, picked.price, picked.uses)});
    } catch (e) {
      console.warn('[TMM Trader] Skipping unavailable premium ' + picked.id + ': ' + e);
    }
  }
  if (chosen.length !== count) throw new Error('Only ' + chosen.length + ' of ' + count + ' premium offers available');
  return chosen;
}

EntityEvents.spawned('minecraft:wandering_trader', event => {
  const trader = event.entity;
  if (trader.level().isClientSide()) return;
  // This prohibition applies even to traders with all stock-version markers.
  tmmPurgeForbiddenTraderOffers(trader);
  const data = trader.getPersistentData();
  const needsCore = data.getInt('tmmGuaranteedMagicStockVersion') < TMM_StockVersion;
  const needsPremium = data.getInt('tmmRotatingMagicStockVersion') < TMM_PremiumVersion;
  const needsCollectible = data.getInt('tmmRelicArtifactStockVersion') < TMM_CollectibleStockVersion;
  if (!needsCore && !needsPremium && !needsCollectible) return;

  // Preserve preexisting original B20 premium stock markers on old traders;
  // upgrading from stock-v1 to rotation-v1 must never duplicate those five.
  if (needsCore) {
    try {
      const required = [
        tmmAffixGear(trader),
        tmmGlyphForTier(trader, 1),
        tmmGlyphForTier(trader, 2),
        tmmGlyphForTier(trader, 3),
        tmmInkOffer(trader)
      ];
      const offers = trader.getOffers();
      const before = offers.size();
      try {
        for (let i = 0; i < required.length; i++) offers.add(required[i]);
      } catch (e) {
        while (offers.size() > before) offers.remove(offers.size() - 1);
        throw e;
      }
      data.putInt('tmmGuaranteedMagicStockVersion', TMM_StockVersion);
      console.info('[TMM Trader] Five base magic offers added: ' + trader.getUUID());
    } catch (e) {
      console.error('[TMM Trader] Five required magic offers FAILED: ' + e);
    }
  }
  if (needsCollectible) {
    try {
      const selected = tmmRandomRelicOrArtifact(trader);
      trader.getOffers().add(selected.offer);
      data.putInt('tmmRelicArtifactStockVersion', TMM_CollectibleStockVersion);
      console.info('[TMM Trader] Guaranteed ' + selected.family + ' collectible ' +
        selected.itemId + ' on trader ' + trader.getUUID());
    } catch (e) {
      console.error('[TMM Trader] Relic/Artifact offer FAILED: ' + e);
    }
  }
  if (needsPremium) {
    try {
      // Four different premium offers, each exactly one of twelve reviewed item types.
      // Avoids a trader GUI with 10+ extra high-value offers at every spawn.
      const chosen = tmmPremiumRotation(trader, 4);
      const offers = trader.getOffers();
      const before = offers.size();
      try {
        for (let i = 0; i < chosen.length; i++) offers.add(chosen[i].offer);
      } catch (e) {
        while (offers.size() > before) offers.remove(offers.size() - 1);
        throw e;
      }
      data.putInt('tmmRotatingMagicStockVersion', TMM_PremiumVersion);
      console.info('[TMM Trader] Four premium rotating offers: ' +
        chosen.map(x => x.id).join(', ') + ' on trader ' + trader.getUUID());
    } catch (e) {
      console.error('[TMM Trader] Premium stock FAILED, no rotation marker set: ' + e);
    }
  }
});
